mapper.sql:
WHERE active AND tier IN ('CORE', 'BROAD')
 AND tier = #{tier}
 AND journal_type = #{journalType}
 AND title ILIKE '%' || #{q} || '%'

mapper.select:
SELECT * FROM source

  AND tier = #{tier}
  AND active = #{active}
  AND position(lower(#{q}) in lower(title)) > 0

ORDER BY id LIMIT #{limit} OFFSET #{offset}
